/bin/bash -lc "rtk python - <<'PY'
import json
for f in ['artifacts/NC-006/accepted_library.json','artifacts/NC-005/checkpoint_manifest.json','artifacts/NC-006/codex_verifier_final.json','artifacts/NC-006/codex_verifier_v2_final.json']:
 d=json.load(open(f)); print('\\n',f, sorted(d.keys()));
 if 'accepted_neural' in d: print(json.dumps(d,indent=2)[:5000])
 if 'checkpoints' in d: print(json.dumps(d['checkpoints'][-8:],indent=2))
 if 'verdict' in d: print('verdict',d['verdict'],'audited',d.get('audited_commit'),'identity',d.get('verifier_type'))
PY
rtk git show --stat --oneline --decorate=short 95aa2e6e3804fab9527de3773d4d15686b51872e
rtk git show --format=fuller --no-ext-diff 95aa2e6e3804fab9527de3773d4d15686b51872e -- artifacts/NC-006/library_manifest.json artifacts/NC-006/accepted_library.json artifacts/NC-006/independent_receipt.json | head -160"

